with open('logs/memory_sync_errors.log', 'r') as f:
    lines = f.readlines()

from collections import Counter

error_types = Counter()
warn_types = Counter()
agents_affected = Counter()
resources_affected = Counter()

for line in lines:
    if '[ERROR]' in line:
        if 'Version conflict' in line:
            error_types['version_conflict'] += 1
            # Extract agent and resource
            parts = line.split()
            for i, p in enumerate(parts):
                if 'agent' in p and ':' not in p:
                    if i > 0 and i+1 < len(parts):
                        agents_affected[p.split()[0]] += 1
                        break
        elif 'Schema mismatch' in line:
            error_types['schema_mismatch'] += 1
        elif 'PII detected' in line:
            error_types['pii_blocked'] += 1
        elif 'Encryption key rotation failed' in line:
            error_types['key_rotation_failed'] += 1
        elif 'Timeout waiting for lock' in line:
            error_types['lock_timeout'] += 1

    if '[WARN]' in line:
        if 'Connection pool exhausted' in line:
            warn_types['pool_exhausted'] += 1
        elif 'Stale data detected' in line:
            warn_types['stale_data'] += 1
        elif 'Sync latency exceeded' in line:
            warn_types['latency_exceeded'] += 1

print('Error types:')
for k, v in error_types.items():
    print(f'  {k}: {v}')

print('\nWarning types:')
for k, v in warn_types.items():
    print(f'  {k}: {v}')

print(f'\nTotal lines: {len(lines)}')
print(f'Total errors: {sum(error_types.values())}')
print(f'Total warnings: {sum(warn_types.values())}')
